    for match in TOKEN_REGEX.finditer(program):
        token = match.group(1).strip()
        if not token: continue

        # Handle comments/separators separately, filtering out pure comments
        if token.startswith('#'):
            continue
        elif token == ';':
            pass
        else:
            tokens.append(token)
    return tokens

